// Official Jagannath University Crest (User Uploaded High-Res PNG)
export const JAGANNATH_UNIVERSITY_LOGO_DATA_URL = "data:image/png;base64,";

export function svgToBase64(svgStr: string): string {
  try {
    return btoa(unescape(encodeURIComponent(svgStr)));
  } catch (e) {
    if (typeof Buffer !== 'undefined') {
      return Buffer.from(svgStr).toString('base64');
    }
    return '';
  }
}